// static
bool UnionTraits<::content::mojom::TestUnion::DataView, ::content::mojom::TestUnionPtr>::Read(
    ::content::mojom::TestUnion::DataView input,
    ::content::mojom::TestUnionPtr* output) {
  using UnionType = ::content::mojom::TestUnion;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kBoolValue: {
      *output = UnionType::NewBoolValue(input.bool_value());
      break;
    }
    case Tag::kInt32Value: {
      *output = UnionType::NewInt32Value(input.int32_value());
      break;
    }
    case Tag::kStringValue: {
      std::string result_string_value{};
      if (!input.ReadStringValue(&result_string_value))
        return false;

      *output = UnionType::NewStringValue(
          std::move(result_string_value));
      break;
    }
    default:

      return false;
  }
  return true;
}

// static
bool UnionTraits<::content::mojom::NestedUnion::DataView, ::content::mojom::NestedUnionPtr>::Read(
    ::content::mojom::NestedUnion::DataView input,
    ::content::mojom::NestedUnionPtr* output) {
  using UnionType = ::content::mojom::NestedUnion;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kInt8Value: {
      *output = UnionType::NewInt8Value(input.int8_value());
      break;
    }
    case Tag::kUnionValue: {
      ::content::mojom::TestUnionPtr result_union_value{};
      if (!input.ReadUnionValue(&result_union_value))
        return false;

      *output = UnionType::NewUnionValue(
          std::move(result_union_value));
      break;
    }
    default:

      return false;
  }
  return true;
}

